import type { ComponentProps } from "@solidjs/web";
import { cn } from "~/lib/utils.ts";
import IconSelector from "~icons/tabler/selector";
import type { Component } from "solid-js";

import { omit } from "solid-js";

type NativeSelectProps =
  & Omit<ComponentProps<"select">, "size">
  & { size?: "sm" | "default" };

const NativeSelect: Component<NativeSelectProps> = (props) => {
  const others = omit(props, "class", "size");
  return (
    <div
      class={cn(
        "group/native-select relative w-fit has-[select:disabled]:opacity-50",
        props.class,
      )}
      data-slot="native-select-wrapper"
      data-size={props.size ?? "default"}
    >
      <select
        data-slot="native-select"
        data-size={props.size ?? "default"}
        class="border-input bg-input/20 placeholder:text-muted-foreground selection:bg-primary selection:text-primary-foreground dark:bg-input/30 dark:hover:bg-input/50 focus-visible:border-ring focus-visible:ring-ring/30 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive dark:aria-invalid:border-destructive/50 h-7 w-full min-w-0 appearance-none rounded-md border py-0.5 pr-6 pl-2 text-xs/relaxed transition-colors select-none focus-visible:ring-2 aria-invalid:ring-2 data-[size=sm]:h-6 data-[size=sm]:text-[0.625rem] outline-none disabled:pointer-events-none disabled:cursor-not-allowed"
        {...others}
      />
      <IconSelector
        class="text-muted-foreground top-1/2 right-1.5 size-3.5 -translate-y-1/2 group-data-[size=sm]/native-select:size-3 group-data-[size=sm]/native-select:-translate-y-[calc(--spacing(1.25))] pointer-events-none absolute select-none"
        aria-hidden="true"
        data-slot="native-select-icon"
      />
    </div>
  );
};

const NativeSelectOption: Component<ComponentProps<"option">> = (props) => {
  const others = omit(props, "class");
  return (
    <option
      data-slot="native-select-option"
      class={cn("bg-[Canvas] text-[CanvasText]", props.class)}
      {...others}
    />
  );
};

const NativeSelectOptGroup: Component<ComponentProps<"optgroup">> = (props) => {
  const others = omit(props, "class");
  return (
    <optgroup
      data-slot="native-select-optgroup"
      class={cn("bg-[Canvas] text-[CanvasText]", props.class)}
      {...others}
    />
  );
};

export type { NativeSelectProps };
export { NativeSelect, NativeSelectOptGroup, NativeSelectOption };
